-- #74 제한적 재지급 (ADR-0155; N01 §2·§9, N02 §8, N04 §5; ADR-0107 결정 2 #73 1·3항, owner answers
-- 2026-11-21). Generated by `drizzle-kit generate`, then hand-edited where marked: this header and
-- the tail. The snapshot is as generated. Additive: a type value, a table and its guards; no
-- existing row changes, so no reset (docs/RESET.md).
--
-- - ledger_entry_type: REGRANT ('재지급'), a mint into the applying member's user ledger account,
--   appended with ADD VALUE — so nothing in this batch names it as the enum (55P04, migrations
--   0014, 0043): the direction function compares text, and the triggers below compare
--   `type::text` in a WHEN and in bodies that run after the batch commits.
-- - regrants: one row per re-grant given, written whole after its REGRANT entry by `applyRegrant`
--   (@buddha/db) and never changed: the request id (Idempotency-Key, unique per account), the
--   amount, the available Coin read under the lock, the entry and its instant.
ALTER TYPE "public"."ledger_entry_type" ADD VALUE 'REGRANT';--> statement-breakpoint
CREATE TABLE "regrants" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"request_id" text NOT NULL,
	"amount_coin" bigint NOT NULL,
	"available_before_coin" bigint NOT NULL,
	"ledger_entry_id" bigint NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "regrants_ledger_entry_id_unique" UNIQUE("ledger_entry_id"),
	CONSTRAINT "regrants_user_id_request_id_unique" UNIQUE("user_id","request_id"),
	CONSTRAINT "regrants_amount_coin_check" CHECK ("regrants"."amount_coin" > 0),
	CONSTRAINT "regrants_available_before_coin_check" CHECK ("regrants"."available_before_coin" >= 0),
	CONSTRAINT "regrants_request_id_check" CHECK ("regrants"."request_id" ~ '^[A-Za-z0-9_-]{8,128}$')
);
--> statement-breakpoint
ALTER TABLE "regrants" ADD CONSTRAINT "regrants_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "regrants" ADD CONSTRAINT "regrants_ledger_entry_id_ledger_entries_id_fk" FOREIGN KEY ("ledger_entry_id") REFERENCES "public"."ledger_entries"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "regrants_user_id_created_at_idx" ON "regrants" USING btree ("user_id","created_at" desc);--> statement-breakpoint
CREATE INDEX "regrants_created_at_id_idx" ON "regrants" USING btree ("created_at" desc,"id" desc);--> statement-breakpoint
-- Hand-edited: which ledger accounts each type moves Coin between, 0060's rows and REGRANT's —
-- a mint into a user ledger account only (LEDGER_ENTRY_RULES, @buddha/shared ledger.ts, which
-- ledger.test.ts keeps equal to this for every type and pair). Same signature, so 0060's trigger
-- (`ledger_entries_check`) calls this body from the commit on.
CREATE OR REPLACE FUNCTION ledger_entry_direction_allowed(entry_type text, from_kind text, to_kind text)
RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT (entry_type, coalesce(from_kind, '-'), coalesce(to_kind, '-')) IN (VALUES
    ('START_GRANT', '-', 'user'),
    ('TREASURY_MINT', '-', 'treasury'),
    ('BOT_ALLOCATION', 'treasury', 'market_maker_funds'),
    ('BOT_RECALL', 'market_maker_funds', 'treasury'),
    ('PAIR_MINT_COLLATERAL', 'user', 'market_collateral'),
    ('PAIR_MINT_COLLATERAL', 'market_maker_funds', 'market_collateral'),
    ('PAIR_BURN_RETURN', 'market_collateral', 'market_maker_funds'),
    ('TRADE_FILL', 'user', 'user'),
    ('TRADE_FILL', 'user', 'market_maker_funds'),
    ('TRADE_FILL', 'market_maker_funds', 'user'),
    ('SETTLEMENT_PAYOUT', 'market_collateral', 'user'),
    ('SETTLEMENT_PAYOUT', 'market_collateral', 'market_maker_funds'),
    ('CLOSURE_FORFEIT', 'user', '-'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'user'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'market_collateral'),
    ('RECONCILIATION_CORRECTION', 'market_collateral', 'treasury'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'market_maker_funds'),
    ('RECONCILIATION_CORRECTION', 'market_maker_funds', 'treasury'),
    ('DEPOSIT', '-', 'user'),
    ('BONUS', '-', 'user'),
    ('PAYMENT_CANCEL', 'user', '-'),
    ('PAYMENT_CANCEL_REVERSAL', '-', 'user'),
    ('REGRANT', '-', 'user')
  );
$$;--> statement-breakpoint
-- Hand-edited: the 운영 마켓메이커 never gets a re-grant (#115, ADR-0107 결정 2 #73 11항): 0059's
-- function, as for its start grant. It has no session to apply with, and no start grant either.
CREATE TRIGGER regrants_human_account
  BEFORE INSERT ON "regrants"
  FOR EACH ROW EXECUTE FUNCTION refuse_operating_account_rows('user_id');--> statement-breakpoint
-- Hand-edited: nor does a closed account (#140): 0043's function, raised with this trigger's name
-- as the constraint, which the API answers as the session that ended (UNAUTHENTICATED) — only a
-- request that passed SessionGuard before the closure committed meets it. The profile row FOR KEY
-- SHARE waits for a closure in flight. The closure forfeits the balance and the ledger takes no
-- entry after it either (0060's `ledger_entries_closed_account`, at COMMIT); this answers first.
CREATE TRIGGER regrants_open_account
  BEFORE INSERT ON "regrants"
  FOR EACH ROW EXECUTE FUNCTION refuse_closed_account_rows();--> statement-breakpoint
-- Hand-edited: a row is its own REGRANT entry's, whoever writes — the entry this row names is a
-- REGRANT referring to this row and keyed by it (`ledgerKeys.regrant`), a mint of this amount into
-- this account's user ledger account, at this row's instant. So the record and the ledger never
-- tell two stories, and a row cannot claim another account's or another type's entry (each entry
-- backs one row: `regrants_ledger_entry_id_unique`). Fires after the two above (by name), so the
-- operating and closed accounts are answered as such. Runs as the invoker: buddha_app may SELECT
-- both tables; the search path is fixed with pg_temp last (0034, 0060).
CREATE FUNCTION regrants_own_entry() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM ledger_entries e
    JOIN ledger_accounts a ON a.id = e.to_account_id
    WHERE e.id = NEW.ledger_entry_id
      AND e.type::text = 'REGRANT'
      AND e.ref_type = 'regrant'
      AND e.ref_id = NEW.id::text
      AND e.idempotency_key = NEW.id::text
      AND e.amount_coin = NEW.amount_coin
      AND e.from_account_id IS NULL
      AND a.kind = 'user'
      AND a.owner_id = NEW.user_id
      AND e.created_at = NEW.created_at
  ) THEN
    RAISE EXCEPTION 're-grant % is recorded only with its own REGRANT ledger entry', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER regrants_own_entry
  BEFORE INSERT ON "regrants"
  FOR EACH ROW EXECUTE FUNCTION regrants_own_entry();--> statement-breakpoint
-- Hand-edited: and a REGRANT entry is recorded only with its row, by the end of its transaction —
-- the type and the reference come together, and the row that names the entry is the one it refers
-- to. Deferred, as the row is inserted after its entry (it names the entry's id). With the trigger
-- above, no Coin is ever re-granted without a record of it, and no record stands without its Coin.
CREATE FUNCTION ledger_entries_regrant_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NOT (NEW.type::text = 'REGRANT' AND NEW.ref_type = 'regrant' AND EXISTS (
    SELECT 1 FROM regrants r WHERE r.ledger_entry_id = NEW.id AND r.id::text = NEW.ref_id
  )) THEN
    RAISE EXCEPTION 'ledger entry % is a re-grant only as its regrants row''s own', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER ledger_entries_regrant_record
  AFTER INSERT ON "ledger_entries"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (NEW.type::text = 'REGRANT' OR NEW.ref_type = 'regrant')
  EXECUTE FUNCTION ledger_entries_regrant_record();--> statement-breakpoint
-- Hand-edited: a re-grant is a permanent fact like its entry, whoever writes; buddha_app loses both
-- privileges below. Emptying the table (the reset, wipe.ts) fires no row trigger.
CREATE FUNCTION regrants_keep_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  RAISE EXCEPTION 're-grant % is a permanent record and takes no %', OLD.id, TG_OP
    USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
END;
$$;--> statement-breakpoint
CREATE TRIGGER regrants_keep_record
  BEFORE UPDATE OR DELETE ON "regrants"
  FOR EACH ROW EXECUTE FUNCTION regrants_keep_record();--> statement-breakpoint
REVOKE UPDATE, DELETE ON TABLE "regrants" FROM buddha_app;
